import { useEffect, useRef } from "react";
import * as THREE from "three";

/**
 * A slow stream of comic panels in 3D. Pages are generated by recursively splitting a rectangle
 * (the way a page layout is cut into panels), then scrolled upward like a webtoon strip.
 * Palette comes from the Sutrid tokens. Pointer tilts the field and moves two coloured lights.
 */

const PALETTE = ["#9d6cff", "#fa625f", "#e8b84a", "#45d3c3", "#6fb0ff", "#62d69d", "#f68fc3"];
const INK = new THREE.Color("#241f3a");

interface Rect { x: number; y: number; w: number; h: number }

function splitPage(r: Rect, depth: number, rnd: () => number, out: Rect[]) {
  const gutter = 0.1;
  if (depth === 0 || (depth < 3 && rnd() < 0.18)) {
    out.push(r);
    return;
  }
  const vertical = r.w / r.h > 0.9 ? rnd() < 0.8 : rnd() < 0.2;
  const t = 0.35 + rnd() * 0.3;
  if (vertical) {
    const w1 = r.w * t - gutter / 2;
    splitPage({ x: r.x, y: r.y, w: w1, h: r.h }, depth - 1, rnd, out);
    splitPage({ x: r.x + w1 + gutter, y: r.y, w: r.w - w1 - gutter, h: r.h }, depth - 1, rnd, out);
  } else {
    const h1 = r.h * t - gutter / 2;
    splitPage({ x: r.x, y: r.y, w: r.w, h: h1 }, depth - 1, rnd, out);
    splitPage({ x: r.x, y: r.y + h1 + gutter, w: r.w, h: r.h - h1 - gutter }, depth - 1, rnd, out);
  }
}

function mulberry(seed: number) {
  return () => {
    seed |= 0;
    seed = (seed + 0x6d2b79f5) | 0;
    let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

export function PanelField({ mode = "hero", className }: { mode?: "bg" | "hero"; className?: string }) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const reduce = matchMedia("(prefers-reduced-motion: reduce)").matches;
    const bg = mode === "bg";

    let renderer: THREE.WebGLRenderer;
    try {
      renderer = new THREE.WebGLRenderer({ canvas, antialias: !bg, alpha: true, powerPreference: "low-power" });
    } catch {
      return; // no WebGL, the CSS grid still carries the look
    }
    renderer.setPixelRatio(Math.min(devicePixelRatio, bg ? 1 : 1.75));
    renderer.setClearColor(0x000000, 0);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(42, 1, 0.1, 100);
    camera.position.set(0, 0, bg ? 26 : 15);

    scene.add(new THREE.AmbientLight(0xffffff, 0.8));
    const key = new THREE.DirectionalLight(0xffffff, 1.1);
    key.position.set(-4, 6, 8);
    scene.add(key);
    const lightA = new THREE.PointLight(0x9d6cff, 70, 30);
    const lightB = new THREE.PointLight(0xfa625f, 50, 30);
    scene.add(lightA, lightB);

    const rnd = mulberry(7);
    const PAGE_W = 5.6, PAGE_H = 7.8, PAGES = 4, COLS = 3;
    const rects: (Rect & { page: number; col: number })[] = [];
    for (let p = 0; p < PAGES; p++) {
      for (let c = 0; c < COLS; c++) {
        const list: Rect[] = [];
        splitPage({ x: 0, y: 0, w: PAGE_W, h: PAGE_H }, 3, rnd, list);
        list.forEach((r) => rects.push({ ...r, x: r.x + (c - (COLS - 1) / 2) * (PAGE_W + 0.5) - PAGE_W / 2, page: p, col: c }));
      }
    }

    const geo = new THREE.BoxGeometry(1, 1, 1);
    const mat = new THREE.MeshStandardMaterial({ roughness: 0.5, metalness: 0.2 });
    const mesh = new THREE.InstancedMesh(geo, mat, rects.length);
    mesh.instanceMatrix.setUsage(THREE.DynamicDrawUsage);
    const base = rects.map((_r, i) => {
      const accent = new THREE.Color(PALETTE[Math.floor(rnd() * PALETTE.length)]!);
      const c = INK.clone().lerp(accent, rnd() < 0.3 ? 0.55 : 0.12 + rnd() * 0.14);
      mesh.setColorAt(i, c);
      return { z: (rnd() - 0.5) * 0.9, tilt: (rnd() - 0.5) * 0.12, depth: 0.12 + rnd() * 0.18 };
    });
    const group = new THREE.Group();
    group.add(mesh);
    group.rotation.set(-0.5, 0.18, 0.2);
    scene.add(group);

    const span = PAGES * (PAGE_H + 0.5);
    const m4 = new THREE.Matrix4();
    const q = new THREE.Quaternion();
    const e = new THREE.Euler();
    const pos = new THREE.Vector3();
    const scl = new THREE.Vector3();
    const place = (t: number) => {
      for (let i = 0; i < rects.length; i++) {
        const r = rects[i]!, b = base[i]!;
        let y = r.y + r.page * (PAGE_H + 0.5) - t;
        y = ((((y + span / 2) % span) + span) % span) - span / 2;
        pos.set(r.x + r.w / 2, -(y + r.h / 2) + 1, b.z);
        e.set(0, 0, b.tilt);
        q.setFromEuler(e);
        scl.set(r.w, r.h, b.depth);
        m4.compose(pos, q, scl);
        mesh.setMatrixAt(i, m4);
      }
      mesh.instanceMatrix.needsUpdate = true;
    };
    place(0);

    const ptr = { x: 0, y: 0, tx: 0, ty: 0 };
    const onMove = (ev: PointerEvent) => {
      const rect = bg ? { left: 0, top: 0, width: innerWidth, height: innerHeight } : canvas.getBoundingClientRect();
      ptr.tx = ((ev.clientX - rect.left) / rect.width) * 2 - 1;
      ptr.ty = ((ev.clientY - rect.top) / rect.height) * 2 - 1;
    };
    addEventListener("pointermove", onMove, { passive: true });

    const resize = () => {
      const w = bg ? innerWidth : canvas.clientWidth;
      const h = bg ? innerHeight : canvas.clientHeight;
      renderer.setSize(w, h, false);
      camera.aspect = w / Math.max(h, 1);
      camera.updateProjectionMatrix();
    };
    resize();
    const ro = new ResizeObserver(resize);
    ro.observe(bg ? document.documentElement : canvas);

    let visible = true;
    const io = new IntersectionObserver(([en]) => (visible = !!en?.isIntersecting));
    io.observe(canvas);

    let raf = 0, last = performance.now(), t = 0, acc = 0;
    const frameGap = bg ? 1000 / 30 : 1000 / 60;
    const speed = bg ? 0.16 : 0.32;
    const tick = (now: number) => {
      raf = requestAnimationFrame(tick);
      const dt = now - last;
      if (!visible || document.hidden || dt < 4) return;
      acc += dt;
      last = now;
      if (acc < frameGap) return;
      const step = Math.min(acc, 100) / 1000;
      acc = 0;
      t += step * speed;
      place(t);
      ptr.x += (ptr.tx - ptr.x) * 0.06;
      ptr.y += (ptr.ty - ptr.y) * 0.06;
      group.rotation.y = 0.18 + ptr.x * 0.16;
      group.rotation.x = -0.5 + ptr.y * 0.08;
      lightA.position.set(ptr.x * 9, -ptr.y * 6 + 2, 6);
      lightB.position.set(-ptr.x * 9, ptr.y * 6 - 2, 5);
      renderer.render(scene, camera);
    };
    if (reduce) renderer.render(scene, camera);
    else raf = requestAnimationFrame(tick);

    return () => {
      cancelAnimationFrame(raf);
      removeEventListener("pointermove", onMove);
      ro.disconnect();
      io.disconnect();
      geo.dispose();
      mat.dispose();
      mesh.dispose();
      renderer.dispose();
    };
  }, [mode]);

  return <canvas ref={ref} className={className} aria-hidden="true" />;
}
